searchText:
blockMeshDict 通过 vertices 定义顶点，以 hex 后的 8 个顶点编号确定块的局部方向和体积符号。(Nx Ny Nz) 指定三个方向的单元数，scale 指定坐标缩放系数，simpleGrading 指定各方向末端与起始单元的尺寸比。 下例建立长 1 m、宽 0.1 m、厚 0.01 m 的二维通道。厚度方向设置一层单元，两侧边界设为 empty。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object blockMeshDict;
}
scale 1;
vertices
(
    (0 0 0) (1 0 0) (1 0.1 0) (0 0.1 0)
    (0 0 0.01) (1 0 0.01) (1 0.1 0.01) (0 0.1 0.01)
);
blocks
(
    hex (0 1 2 3 4 5 6 7) (100 20 1)
        simpleGrading (1 1 1)
);
edges ();
boundary
(
    inlet
    {
        type patch;
        faces ((0 4 7 3));
    }
    outlet
    {
        type patch;
        faces ((1 2 6 5));
    }
    walls
    {
        type wall;
        faces ((0 1 5 4) (3 7 6 2));
    }
    frontAndBack
    {
        type empty;
        faces ((0 3 2 1) (4 5 6 7));
    }
);
mergePatchPairs (); 执行 blockMesh 生成网格，再执行 checkMesh -allTopology -allGeometry 检查拓扑和几何。边界面的顶点顺序按外法向排列；多块网格应统一局部坐标和顶点编号。 参数或结构 设置方法 使用条件 scale 如 0.001 表示原坐标按毫米给出 采用 scale 统一设置坐标缩放 simpleGrading 例如 (1 10 1) 沿块的局部方向设置；反向时取对应倒数 多段 grading 某方向可写 ((0.2 0.3 4) (0.6 0.4 1) (0.2 0.3 0.25)) 每段分别为长度比例、单元比例、扩张比 edgeGrading 对 12 条局部边分别指定扩张比 按块的局部边编号依次赋值 edges arc 0 1 (中间点)，或 spline、polyLine 弧线端点与控制点应满足非退化条件 boundary/type patch、wall、empty、symmetryPlane、wedge、cyclic 等 定义网格边界类型；场边界另行配置 defaultPatch 为未显式列出的面指定名称和类型 显式边界之外的面归入该边界 mergePatchPairs ((patchA patchB)) 合并指定的块接口

snappyHexMesh 包括切割细化、表面贴合和边界层生成三个阶段。运行 foamGetDict snappyHexMeshDict 获取带注释模板，在已建立的背景网格上配置几何和各阶段参数。 参数 含义 设置方法 castellatedMesh、snap、addLayers 分别控制切割细化、贴体和边界层生成 先检查切割细化和贴体，再配置边界层 geometry 表面及可搜索几何体 body.stl { type triSurfaceMesh; name body; } maxLocalCells、maxGlobalCells 局部及全局细化控制限额 根据可用内存设置单元数量上限 minRefinementCells 停止继续细化的候选单元阈值 设为 0 时继续处理剩余细化单元，计算量相应增加 nCellsBetweenLevels 相邻细化级别间的过渡层数 例如 3 features 显式特征文件和细化等级 ({ file "body.eMesh"; level 2; }) refinementSurfaces 表面的最小最大细化等级 body { level (2 3); patchInfo { type wall; } } resolveFeatureAngle 区分尖锐表面特征的角度 示例为 30，按表面几何特征确定 refinementRegions 体积或距离带细化 mode inside、outside 或 distance；levels 定义等级 locationInMesh 标记需要保留的连通流体区域 取目标流体区域内部点，避开边界面 allowFreeStandingZoneFaces 是否允许独立区域面 与 zone 生成方式匹配 snapControls 贴体松弛和迭代 nSmoothPatch、tolerance、nSolveIter、nRelaxIter 显式特征贴合 explicitFeatureSnap 与 nFeatureSnapIter 与 features 中的 eMesh 配合 layers 各 patch 的层数 "body.*" { nSurfaceLayers 3; } relativeSizes 层厚是否相对外层网格尺寸 true 相对尺寸；false 绝对长度 expansionRatio 层间厚度增长比 例如 1.2 finalLayerThickness、firstLayerThickness、thickness 不同的层厚约束 按层厚参数关系选取相容组合 minThickness 允许保留的最小总层厚指标 阈值过大时，局部边界层将被取消 nGrow、nBufferCellsNoExtrude 尖角附近的非挤出区域及过渡缓冲 控制未生成边界层区域的过渡 featureAngle、slipFeatureAngle 层网格遇尖角时的行为 按几何特征及边界层覆盖率调整 nLayerIter、nRelaxedIter 边界层生成迭代及质量阈值放宽迭代 几何有效性满足要求后设置迭代上限 meshQualityControls 质量约束 通常包含系统 meshQualityDict mergeTolerance 点合并相对容差 常用 1e-6，以几何包围盒尺度为基准 // 片段：放入对应的 snappyHexMeshDict
geometry
{
    body.stl { type triSurfaceMesh; name body; }
    refineBox
    {
        type searchableBox;
        min (-0.2 -0.2 -0.2);
        max (1.2 0.2 0.2);
    }
}
castellatedMeshControls
{
    maxLocalCells 1000000;
    maxGlobalCells 3000000;
    minRefinementCells 0;
    nCellsBetweenLevels 3;
    features ({ file "body.eMesh"; level 2; });
    refinementSurfaces
    {
        body { level (2 3); patchInfo { type wall; } }
    }
    resolveFeatureAngle 30;
    refinementRegions
    {
        refineBox { mode inside; levels ((1e15 2)); }
    }
    locationInMesh (2 0 0);
    allowFreeStandingZoneFaces true;
}
snapControls
{
    nSmoothPatch 3; tolerance 2.0;
    nSolveIter 30; nRelaxIter 5;
    nFeatureSnapIter 10;
    implicitFeatureSnap false;
    explicitFeatureSnap true;
    multiRegionFeatureSnap false;
} locationInMesh 中的 (2 0 0) 表示待保留流体区域内的一点，该点须位于背景网格范围内及物体外部。网格生成前应消除 STL 自相交，统一长度单位，并检查背景网格。 边界层生成配置如下。snapControls 和质量控制参数保留模板中的完整设置。将 addLayers 设为 false，可单独检查切割细化和表面贴合结果。 castellatedMesh true;
snap true;
addLayers true;
addLayersControls
{
    relativeSizes true;
    layers { body { nSurfaceLayers 3; } }
    expansionRatio 1.2;
    finalLayerThickness 0.3;
    minThickness 0.1;
    nGrow 0;
    featureAngle 60;
    nRelaxIter 5;
    nSmoothSurfaceNormals 1;
    nSmoothNormals 3;
    nSmoothThickness 10;
    maxFaceThicknessRatio 0.5;
    maxThicknessToMedialRatio 0.3;
    minMedialAxisAngle 90;
    nBufferCellsNoExtrude 0;
    nLayerIter 50;
}
meshQualityControls
{
    #includeEtc "caseDicts/meshQualityDict"
}
mergeTolerance 1e-6;

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object surfaceFeatureExtractDict;
}
body.stl
{
    extractionMethod extractFromSurface;
    extractFromSurfaceCoeffs { includedAngle 150; }
    writeObj yes;
} 输入表面 body.stl 存放于 constant/triSurface。includedAngle 按特征提取器的包含角定义取值，其定义与 resolveFeatureAngle 不同。writeObj 控制可视化文件输出。运行 surfaceFeatureExtract 后，将生成的 eMesh 文件名用于后续特征线配置。 body.stl
{
    extractionMethod    extractFromSurface;
    includedAngle       150;          // 夹角超过它的棱视为特征边
    subsetFeatures      { nonManifoldEdges no; openEdges yes; }
    writeObj            yes;          // 输出 obj 方便在 ParaView 里检查
} includedAngle 越大，提取的边越多。150 是常用起点：太小会漏掉圆角过渡处的特征，太大会把曲面上的三角片棱也当成特征。

setFields 首先按 defaultFieldValues 设置全域初值，再依次执行 regions 中的区域赋值。区域重叠时，后续赋值覆盖先前结果。目标场文件须预先建立，并设置相应的 class 和 dimensions。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object setFieldsDict;
}
defaultFieldValues
(
    volScalarFieldValue alpha.water 0
    volVectorFieldValue U (0 0 0)
);
regions
(
    boxToCell
    {
        box (0 0 -1) (0.2 0.3 1);
        fieldValues (volScalarFieldValue alpha.water 1);
    }
); boxToCell 按单元位置选取长方体区域；sphereToCell 通过 centre 和 radius 定义球形区域；cylinderToCell 通过 p1、p2 和 radius 定义圆柱区域。边界面可采用 boxToFace 等选择器。 赋值后检查 alpha.water 的极值与空间分布，边界条件在场文件中另行设置。需采用数学表达式赋值时，使用 setExprFields。 defaultFieldValues              // 先把全场设成默认值
(
    volScalarFieldValue alpha.water 0
    volVectorFieldValue U (0 0 0)
);

regions                          // 再覆盖指定区域
(
    boxToCell
    {
        box (0 0 -1) (0.1461 0.292 1);
        fieldValues ( volScalarFieldValue alpha.water 1 );
    }

    cylinderToCell
    {
        p1 (0 0 0);  p2 (0 0 0.1);  radius 0.05;
        fieldValues ( volScalarFieldValue T 500 );
    }

    sphereToCell
    {
        origin (0 0 0);  radius 0.1;
        fieldValues ( volScalarFieldValue p 1e6 );
    }
); 常用区域类型：boxToCell、sphereToCell、cylinderToCell、rotatedBoxToCell、surfaceToCell（用 STL 划区）、cellToCell（用已有 cellSet）、zoneToCell。 注意：setFields 直接修改 0/ 里的文件。跑之前先 cp -r 0.orig 0，否则第二次运行是在被改过的场上再改一次。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object setExprFieldsDict;
}
expressions
(
    setTemperature
    {
        field T;
        expression "300 + 10*pos().x()";
    }
); 下例在已有温度场 T 上设置随坐标变化的温度，运行 setExprFields 后生效。fieldMask 限定赋值区域，create 和 dimensions 用于新建场。表达式语法可通过 foamExprParserInfo 查询。边界表达式使用 setExprBoundaryFieldsDict，其结构按边界场接口配置。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object topoSetDict;
}
actions
(
    {
        name heaterCells;
        type cellSet;
        action new;
        source boxToCell;
        box (0.2 0 0) (0.4 0.1 0.01);
    }
    {
        name heater;
        type cellZoneSet;
        action new;
        source setToCellZone;
        set heaterCells;
    }
); 条目 含义 设置方法与取值 name 输出集合或区域名称 与源项中的 cellZone 匹配 type 对象类别 cellSet、faceSet、pointSet、cellZoneSet、faceZoneSet action 集合操作 new、add、subtract、subset、invert、clear、remove source 选择算法 boxToCell、sphereToCell、cylinderToCell、patchToFace、fieldToCell 等 sourceInfo 选择源参数子字典 多数选择源可将参数直接写入动作字典；名称冲突时采用 sourceInfo actions
(
    {
        name    c0;
        type    cellSet;        // cellSet / faceSet / pointSet / cellZoneSet / faceZoneSet
        action  new;            // new / add / subtract / subset / invert / clear / remove
        source  boxToCell;
        box     (0 0 0) (1 1 1);
    }
    {
        name    porous;
        type    cellZoneSet;
        action  new;
        source  setToCellZone;
        set     c0;
    }
); 常用 source 一览 类别 source 关键参数 几何选单元 boxToCell box (min) (max) 或 boxes ((..)(..))  rotatedBoxToCell origin, i, j, k  sphereToCell origin, radius  cylinderToCell p1, p2, radius  surfaceToCell file "x.stl", outsidePoints, includeCut 拓扑选单元 zoneToCell / setToCell / labelToCell zone/set/value  cellToCell set 选面 boxToFace、patchToFace、normalToFace、cellToFace   boundaryToFace 全部边界面 选点 boxToPoint、labelToPoint、surfaceToPoint  转 zone setToCellZone、setsToFaceZone、setToPointZone  Set 与 Zone 的区别（重要）：Set 是临时选择结果，写在 constant/polyMesh/sets/；Zone 是网格的正式组成部分，写进 cellZones/faceZones。求解器里的多孔介质、MRF、fvOptions、动网格全都认 Zone 不认 Set，所以典型流程是”先 xxxToCell 造 Set，再 setToCellZone 转 Zone”。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object createPatchDict;
}
pointSync false;
patches
(
    {
        name walls;
        patchInfo { type wall; }
        constructFrom patches;
        patches (wallA wallB);
    }
); constructFrom patches 从已有边界选面；constructFrom set 从指定 faceSet 选面。pointSync 控制耦合点同步。执行 createPatch -overwrite 后，将 0/U、0/p 等场文件中的边界条目与新建 walls 对应。 pointSync false;

patches
(
    {
        name            cyclicLeft;
        patchInfo       { type cyclic; neighbourPatch cyclicRight; }
        constructFrom   patches;
        patches         (left);
    }
); 用途：把网格转换器生成的一堆零散 patch 合并；把两个面配成周期边界；改 patch 类型。

createBaffles 将内部面转换为成对边界面。internalFacesOnly 控制选面范围，baffles 定义各挡板的 type、zoneName 和 patches。下例采用预先建立的 interfaceZone 面区域。 internalFacesOnly true;
baffles
{
    interface
    {
        type faceZone;
        zoneName interfaceZone;
        patches
        {
            master { name sideA; type wall; }
            slave  { name sideB; type wall; }
        }
    }
} 运行 createBaffles -overwrite 生成挡板边界。两侧的传热和流动耦合由场边界条件及物理模型确定。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object refineMeshDict;
}
set heaterCells;
coordinateSystem global;
globalCoeffs
{
    tan1 (1 0 0);
    tan2 (0 1 0);
}
directions (tan1 tan2);
useHexTopology true;
geometricCut false;
writeMesh false; set 指定待细化的单元集合，directions 指定细化方向。二维网格仅沿面内方向细化，厚度方向保持 empty 边界要求的单层结构。运行 refineMesh -overwrite 后，检查场、区域和边界与新网格的对应关系。 set             c0;                 // 对哪个 cellSet 加密
coordinateSystem global;
globalCoeffs    { tan1 (1 0 0); tan2 (0 1 0); }
directions      ( tan1 tan2 );      // 只在这两个方向加密（各向异性）
useHexTopology  yes;
geometricCut    no;
writeMesh       no; $ topoSet && refineMesh -overwrite -dict system/refineMeshDict

constructFrom 指定挤出来源，sourceCase 和 sourcePatches 指定源算例及边界，exposedPatchName 定义新暴露边界。extrudeModel 选择挤出模型，nLayers 和 expansionRatio 控制层数及层厚比，mergeFaces 和 mergeTol 控制合并。linearNormal 通过 linearNormalCoeffs/thickness 设置总厚度；其他模型采用各自的系数字典。 // 片段：沿已有 patch 外法向挤出
constructFrom patch;
sourceCase ".";
sourcePatches (front);
exposedPatchName back;
extrudeModel linearNormal;
nLayers 5;
expansionRatio 1;
linearNormalCoeffs { thickness 0.01; }
mergeFaces false;
mergeTol 0; constructFrom   patch;              // mesh / patch / surface
sourceCase      "../base";
sourcePatches   (front);
exposedPatchName back;

extrudeModel    linearNormal;       // linearNormal/linearDirection/wedge/sector/plane
linearNormalCoeffs { thickness 0.01; }
sectorCoeffs   { axisPt (0 0 0); axis (0 0 1); angle 5; }

nLayers         1;
expansionRatio  1.0;
mergeFaces      false; 典型用途：把一个二维面拉伸成一层网格做二维算例；用 sector 模型做轴对称（wedge）算例。

mapFieldsDict 用于源算例与目标算例边界不一致时的场映射。patchMap 中每组名称依次为目标边界和源边界。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object mapFieldsDict;
}
patchMap
(
    inlet sourceInlet
    outlet sourceOutlet
);
cuttingPatches (newCutBoundary); 在目标算例中执行 mapFields ../sourceCase -sourceTime latestTime。cuttingPatches 指定切穿源计算域的目标边界，其数值由源域内部插值得到。-consistent 适用于边界拓扑匹配的算例。映射体积分数等守恒量后，应检查有界性及积分守恒。 patchMap        ( inlet1 inlet );   // 源算例 patch → 目标算例 patch
cuttingPatches  ( outlet );         // 被切开的 patch（源网格不覆盖的部分） 网格边界一致时可以完全不用这个文件，直接 mapFields ../src -consistent。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object changeDictionaryDict;
}
dictionaryReplacement
{
    U
    {
        boundaryField
        {
            inlet { type fixedValue; value uniform (2 0 0); }
        }
    }
} dictionaryReplacement 按目标文件名组织替换条目，运行 changeDictionary 后写回相应文件。-instance 指定目标实例目录。单个键值可直接通过 foamDictionary 修改。 dictionaryReplacement
{
    boundary
    {
        minZ { type wall; }
    }
    U
    {
        boundaryField
        {
            "(inlet|outlet)" { type zeroGradient; }
        }
    }
} 多区域算例（chtMultiRegionFoam）里，每个 region 一份，放在 system/<region>/changeDictionaryDict。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object controlDict;
}
application pimpleFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 1;
deltaT 0.001;
writeControl adjustableRunTime;
writeInterval 0.05;
purgeWrite 0;
writeFormat ascii;
writePrecision 8;
writeCompression off;
timeFormat general;
timePrecision 8;
runTimeModifiable true;
adjustTimeStep true;
maxCo 0.5;
maxDeltaT 0.01;
functions {}; 参数 含义与可选值 设置方法 application 供运行脚本选择的应用名称 脚本按此项调用程序；终端直接调用时执行指定程序 startFrom startTime、firstTime、latestTime 续算通常用 latestTime startTime 开始时刻 在采用相应 startFrom 模式时读取 stopAt endTime、writeNow、noWriteNow、nextWrite 指定停止时刻及结果写出方式 endTime 结束时刻或稳态迭代终点 稳态求解中的时间可表示迭代计数 deltaT 时间步或迭代步 瞬态计算按时间精度及稳定性确定 writeControl timeStep、runTime、adjustableRunTime、cpuTime、clockTime 等 timeStep 下 writeInterval 是步数；runTime 下是模拟时间 writeInterval 输出间隔 由 writeControl 确定单位，并按瞬态特征设置间隔 purgeWrite 仅保留最近若干常规输出时刻 0 保留全部输出；正整数指定保留的最近时刻数 writeFormat、writePrecision 格式与有效数字 ASCII 便于检查；binary 减少 IO writeCompression 输出压缩 on 或 off，后处理软件需支持相应格式 timeFormat、timePrecision 时间目录命名格式和精度 精度应能区分相邻输出时刻 runTimeModifiable 运行中重新读取可修改字典 可修改范围由模型和求解器的读取机制确定 adjustTimeStep、maxCo、maxDeltaT 自动时间步控制 仅在实现相应时间步控制的求解器中生效 maxAlphaCo VOF 相分数相关 Courant 限制 仅相关求解器使用 maxDi 热扩散数控制 仅相关传热求解器使用 libs 加载自定义或功能库 例如 ("libMyBC.so") functions 运行时函数对象 见第 10 章 Courant 数由局部速度、通量、单元尺寸和时间步共同决定。可压缩激波计算还需考虑声速约束，时间步上限应结合所用求解器和离散格式确定。 它管什么：算多久、多久输出一次、用什么求解器、跑哪些后处理。每个算例必需。

下例给出不可压缩非稳态层流的离散设置。采用湍流模型或求解能量方程时，应补充相应方程的对流项。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object fvSchemes;
}
ddtSchemes { default Euler; }
gradSchemes { default Gauss linear; }
divSchemes
{
    default none;
    div(phi,U) Gauss linearUpwind grad(U);
    div((nuEff*dev2(T(grad(U))))) Gauss linear;
}
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
wallDist { method meshWave; } 字典 控制对象 常用设置 ddtSchemes 时间导数 Euler 为一阶；backward 为二阶；CrankNicolson 0.9 为混合格式；steadyState 用于稳态 gradSchemes 梯度 Gauss linear、leastSquares、cellLimited Gauss linear 1 divSchemes 对流及显式散度 Gauss upwind 耗散较强；linearUpwind 阶数较高；limitedLinear 等限制格式按字段类型选择 laplacianSchemes 扩散项 常用 Gauss linear corrected；非正交程度较高时可采用 limited 修正 interpolationSchemes 面插值 linear 等 snGradSchemes 面法向梯度 corrected、uncorrected、limited 0.5 等 fluxRequired 指定需保留通量的场 按求解器要求标记 p 等场 wallDist 壁距算法 meshWave 等 default none 无默认格式 所需离散项必须显式配置，缺失时报告错误 湍流方程可采用 div(phi,k) Gauss upwind; 和 div(phi,omega) Gauss upwind;，字段名称随模型确定。VOF 求解器的 div(phi,alpha)、div(phirb,alpha) 等条目采用其配套教程的定义。rhoCentralFoam 还需设置 fluxScheme 及变量重构格式。 它管什么：每一项微分算子用什么数值格式离散。这是精度与稳定性的主要旋钮，也是初学者最容易被卡住的地方。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object fvSolution;
}
solvers
{
    p
    {
        solver GAMG;
        tolerance 1e-7;
        relTol 0.05;
        smoother GaussSeidel;
    }
    pFinal { $p; relTol 0; }
    U
    {
        solver smoothSolver;
        smoother symGaussSeidel;
        tolerance 1e-8;
        relTol 0;
    }
}
PIMPLE
{
    nOuterCorrectors 2;
    nCorrectors 2;
    nNonOrthogonalCorrectors 0;
    momentumPredictor yes;
    pRefCell 0;
    pRefValue 0;
}
relaxationFactors
{
    equations { U 1; }
} 条目 含义 设置原则 solver 线性代数求解器 PCG 适于相容的对称矩阵；PBiCGStab 可处理非对称矩阵；GAMG 为多重网格 preconditioner 预条件器 DIC、DILU 等须与矩阵和 solver 相容 smoother 平滑器 如 GaussSeidel、symGaussSeidel、DICGaussSeidel tolerance 绝对残差停止阈值 控制线性方程残差的停止条件 relTol 相对本次求解初始残差的停止阈值 0 表示关闭相对阈值，常用于最终校正 minIter、maxIter 线性迭代上下限 达到 maxIter 时结合残差判断收敛状态 nSweeps 每组平滑扫描次数 仅适用求解器使用 cacheAgglomeration 缓存 GAMG 聚合 静态网格可复用聚合结果 nCellsInCoarsestLevel GAMG 最粗层目标单元数 结合并行分区和收敛情况调整 pFinal、UFinal 等 最后一次校正的专用设置 是否使用由求解器控制 正则字段名 共享线性求解配置 如 "(U|k|omega)"，采用引号包围正则表达式 relaxationFactors/fields 场松弛 如稳态 p 0.3 relaxationFactors/equations 方程松弛 如稳态 U 0.7；较小因子降低更新幅度 SIMPLE、PISO 和 PIMPLE 分别采用对应的算法子字典。SIMPLE 常用 nNonOrthogonalCorrectors、consistent、residualControl 和 pRefCell/pRefValue；PISO 通过 nCorrectors 控制校正次数；PIMPLE 另设 nOuterCorrectors 控制外迭代。压力方程需要参考值且求解器采用该机制时，设置 pRefCell 和 pRefValue。 // SIMPLE 片段：稳态算例
SIMPLE
{
    nNonOrthogonalCorrectors 0;
    residualControl
    {
        p 1e-5;
        U 1e-6;
        "(k|omega)" 1e-6;
    }
}
relaxationFactors
{
    fields { p 0.3; }
    equations { U 0.7; k 0.7; omega 0.7; }
} residualControl 的结构由算法接口确定，部分 PIMPLE 控制采用 tolerance/relTol 子字典。收敛判定应同时考察残差、质量守恒及力、流量、温度等目标量的稳定性。 它管什么：每个方程用什么线性代数求解器、迭代到什么精度、外层算法（SIMPLE/PISO/PIMPLE）怎么循环、松弛因子多少。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object decomposeParDict;
}
numberOfSubdomains 4;
method scotch; numberOfSubdomains 指定分区数，与求解阶段 mpirun -np 的进程数一致。scotch 采用图分割，simple 按坐标规则划分，hierarchical 按指定方向依次划分，manual 使用给定的处理器映射，multiLevel 组合多级分解方法。 // 用 simple 替换上面的 method 时，加入以下系数
method simple;
simpleCoeffs
{
    n (2 2 1);
    delta 0.001;
} 示例中 n 的三个分量乘积为 4。hierarchicalCoeffs 还通过 order 指定划分顺序，如 xyz。多区域算例可在 regions 子字典中分别设置方法和子域数。constraints 用于保持挡板、面区域及指定连接关系，约束范围同时影响负载均衡。 numberOfSubdomains  8;          // 必须等于 mpirun -np 的数字

method              scotch;     // 分区算法

// 各算法的参数（只需写你用的那个）
simpleCoeffs    { n (2 2 2); delta 0.001; }        // 按 x/y/z 均分
hierarchicalCoeffs { n (2 2 2); delta 0.001; order xyz; }
manualCoeffs    { dataFile "decompositionData"; } method 说明 何时用 scotch 自动最小化交界面，默认首选 绝大多数情况 hierarchical 按指定顺序在 x/y/z 上依次均分 规则区域、想控制分区形状 simple 直接三向均分 简单几何 kahip / metis 其他图分区库 有装才有 multiLevel 多级分区（跨节点/节点内分别优化） 大规模集群 structured 沿某方向不切（保持结构） 边界层方向不切分 manual 读文件指定每个单元归谁 特殊需求 约束条件（保证某些面不被切开）： constraints
{
    baffles       { type preserveBaffles; }
    cyclics       { type preservePatches; patches (cyc1 cyc2); }
    faces         { type singleProcessorFaceSets; sets ((f0 -1)); }
} n (2 2 2) 的乘积必须等于 numberOfSubdomains，写不一致会直接报错。

不可压缩牛顿流体的配置如下。求解器可直接读取 nu，也可通过 transportModel 创建输运模型，相应条目采用该求解器的配置结构。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object transportProperties;
}
transportModel Newtonian;
nu [0 2 -1 0 0 0 0] 1e-6; nu 为运动黏度，mu 为动力黏度，两者满足 mu = rho*nu。powerLaw、BirdCarreau 等非牛顿模型采用各自的系数字典，参数定义见对应模型源码和教程。 不可压缩 VOF 的两相物性配置如下。 phases (water air);
water { transportModel Newtonian; nu 1e-6; rho 1000; }
air   { transportModel Newtonian; nu 1.5e-5; rho 1.2; }
sigma 0.072; rho 表示相密度，sigma 表示表面张力系数。示例数值为常温条件下的近似示例。可压缩多相模型通常分别设置各相热物性。 单相不可压 transportModel  Newtonian;
nu              [0 2 -1 0 0 0 0] 1e-05;      // 运动粘度 m²/s
// 新版也可以简写（量纲由程序推断）：nu 1e-05; 非牛顿流体可选 CrossPowerLaw、BirdCarreau、HerschelBulkley、powerLaw，各自再跟一个系数子字典。 两相（interFoam） phases (water air);

water { transportModel Newtonian; nu 1e-06; rho 1000; }
air   { transportModel Newtonian; nu 1.48e-05; rho 1; }

sigma  0.07;          // 表面张力系数 N/m laplacianFoam DT              [0 2 -1 0 0 0 0] 4e-05;      // 扩散系数

v2512 常见流体求解器通过 turbulenceProperties 配置湍流，RASModel 和 LESModel 分别指定 RAS 与 LES 模型。Foundation 分支采用的 momentumTransport 属于另一套配置接口。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object turbulenceProperties;
}
simulationType RAS;
RAS
{
    RASModel kOmegaSST;
    turbulence on;
    printCoeffs on;
} 层流采用 simulationType laminar;。LES 可采用 simulationType LES; LES { LESModel WALE; turbulence on; printCoeffs on; delta cubeRootVol; }。 LES 配置还需确定滤波宽度、近壁处理、入口脉动和时间分辨率，并与网格及边界条件配合。 simulationType  RAS;          // laminar / RAS / LES

RAS
{
    RASModel        kOmegaSST;
    turbulence      on;
    printCoeffs     on;        // 启动时把模型系数打印到日志，便于确认
} simulationType  LES;

LES
{
    LESModel        WALE;              // 或 Smagorinsky / kEqn / dynamicKEqn
    delta           cubeRootVol;       // 滤波尺度：cubeRootVol / vanDriest / smooth
    turbulence      on;
    printCoeffs     on;

    cubeRootVolCoeffs { deltaCoeff 1; }
} 常用 RANS 模型怎么挑 模型 特点 场合 kEpsilon 最经典，壁面靠壁函数 内流、自由剪切流 realizableKE 对旋转/分离更好 旋流 kOmegaSST 近壁用 k-ω、远场用 k-ε，逆压梯度和分离预测好 外流绕流、翼型，最常用 SpalartAllmaras 单方程，便宜 航空外流 LaunderSharmaKE 低雷诺数版本，需要 y⁺≈1 不用壁函数时 v2512 的 kEpsilon 新增 twoLayerTreatment 开关，可以在近壁内层用代数关系式，降低对第一层网格的要求： RAS
{
    RASModel        kEpsilon;
    turbulence      on;
    kEpsilonCoeffs  { twoLayerTreatment true; }
} 层流就写 simulationType laminar;，此时 0/ 里不需要 k、epsilon、nut 等文件。

下例采用单相理想气体、常热容和常输运系数，能量变量为显焓。热物性类型和能量形式应与求解器接口对应。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object thermophysicalProperties;
}
thermoType
{
    type hePsiThermo;
    mixture pureMixture;
    transport const;
    thermo hConst;
    equationOfState perfectGas;
    specie specie;
    energy sensibleEnthalpy;
}
mixture
{
    specie { molWeight 28.96; }
    thermodynamics { Cp 1005; Hf 0; }
    transport { mu 1.8e-5; Pr 0.7; }
} 参数 作用 设置方法 type 热物性基类 hePsiThermo、heRhoThermo 等；须与求解器匹配 mixture 混合物模型 pureMixture 单组分；反应流使用相应多组分模型 transport 输运模型 const、sutherland 等 thermo 热容模型 hConst 常热容；janaf 温度相关多项式 equationOfState 状态方程 perfectGas、rhoConst 等，按介质状态关系选择 energy 能量变量 sensibleEnthalpy 或 sensibleInternalEnergy 等 molWeight 摩尔质量 单位为 kg/kmol，空气示例为 28.96 Cp、Hf 定压比热、生成焓 按模型定义及参考态赋值 mu、Pr 动力黏度和 Prandtl 数 采用一致的单位与适用温度范围 As、Ts Sutherland 输运系数 选择 sutherland 后按该模型填写 Tlow、Thigh、Tcommon、lowCpCoeffs、highCpCoeffs JANAF 温度区间及系数 从可靠物性数据或机理文件提取 rhoCentralFoam 等采用相应的热物性基类和能量变量。使用显内能的求解器应配置 sensibleInternalEnergy，并保留配套教程中的热物性组合。 thermoType
{
    type            hePsiThermo;          // hePsiThermo(可压理想气体) / heRhoThermo(液体)
    mixture         pureMixture;          // 单组分
    transport       sutherland;           // const / sutherland / polynomial
    thermo          janaf;                // hConst / eConst / janaf
    equationOfState perfectGas;           // perfectGas / rhoConst / Boussinesq / PengRobinson
    specie          specie;
    energy          sensibleInternalEnergy;   // sensibleEnthalpy / sensibleInternalEnergy
}

mixture
{
    specie          { molWeight  28.96; }
    thermodynamics  { Cp 1004.5; Hf 0; }
    transport       { mu 1.8e-05; Pr 0.7; }
} 七个字段各自的意思：type 决定用 ψ(=1/RT) 还是 ρ 作为基本量；mixture 是单组分还是多组分；transport 是粘性/导热系数的模型；thermo 是比热模型（hConst 常数比热，janaf 用 JANAF 多项式）；equationOfState 是状态方程；energy 是用焓还是内能作为求解变量。修改时七个字段必须相互兼容，不兼容时报错信息会把所有合法组合列出来——照着报错里的列表挑就行，这是 OpenFOAM 少数几个报错比文档还好用的地方。 sensibleEnthalpy 还是 sensibleInternalEnergy：基于压力的求解器（rhoPimpleFoam）一般用焓；基于密度的（rhoCentralFoam）用内能。照抄对应教程即可。

fvOptions 用于配置源项和约束，文件位置由求解器的读取路径确定，常见于 constant 或 system。下例在指定 cellZone 内施加速度方程源项，采用 sources 条目。 FoamFile
{
    version 2.0; format ascii;
    class dictionary; object fvOptions;
}
drive
{
    type vectorSemiImplicitSource;
    active true;
    selectionMode cellZone;
    cellZone heater;
    volumeMode specific;
    sources
    {
        U ((0.1 0 0) 0);
    }
} 半隐式源项写为 Su + Sp*字段，括号内依次给出显式项和隐式系数。specific 按单位体积定义，absolute 按所选体积的总量定义。源项量纲取决于控制方程；速度、动量以及以 h、e 或 T 为变量的能量方程应分别确定量纲和密度因子。 selectionMode 指定作用范围，可选 all、cellZone、cellSet 等；timeStart 和 duration 指定作用时间。常用类型包括 scalarSemiImplicitSource、vectorSemiImplicitSource、meanVelocityForce、explicitPorositySource、scalarFixedValueConstraint、limitTemperature 和 codedSource，其参数按对应模型设置。 放在 system/fvOptions（或 constant/fvOptions）。它让你不改求解器就能加源项。 momentumSource
{
    type            meanVelocityForce;      // 恒定流量驱动（周期性槽道流必用）
    active          yes;
    selectionMode   all;
    fields          (U);
    Ubar            (0.1335 0 0);
}

heatSource
{
    type            scalarSemiImplicitSource;
    active          yes;
    selectionMode   cellZone;
    cellZone        heater;
    volumeMode      absolute;               // absolute / specific
    sources         { h (500 0); }          // (显式部分 隐式部分)
}

porous
{
    type            explicitPorositySource;
    active          yes;
    selectionMode   cellZone;
    cellZone        porousZone;
    type            DarcyForchheimer;
    d   (5e7 -1000 -1000);
    f   (0 0 0);
    coordinateSystem { ... }
}

MRF1
{
    type            MRFSource;             // 旋转参考系（风机、搅拌器）
    selectionMode   cellZone;
    cellZone        rotor;
    origin          (0 0 0);
    axis            (0 0 1);
    omega           constant 104.72;       // rad/s
} 常用类型还有：limitTemperature（限温，防发散）、limitVelocity、fixedTemperatureConstraint、buoyancyEnergy、radiation、solidificationMeltingSource（相变）、atmAmbientTurbSource（大气边界层）。 为什么它重要：初学者遇到”我要在某个区域加个热源/阻力/旋转”，第一反应常是去改求解器源码。用 fvOptions 一个字典就能解决，且不影响可维护性。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object MRFProperties;
}
rotorZone
{
    active yes;
    cellZone rotor;
    nonRotatingPatches (stator);
    origin (0 0 0);
    axis (0 0 1);
    omega constant 100;
} rotor 为预先建立的 cellZone，omega 的单位为 rad/s。nonRotatingPatches 指定区域内保持静止的边界。MRF 在固定网格上采用旋转参考系近似处理。 SRFProperties 配置单参考系模型，常用 SRFModel rpm 和 rpmCoeffs/rpm，以 rpm 表示转速。使用两种模型时应分别采用对应的角速度单位。

FoamFile
{
    version 2.0; format ascii;
    class dictionary; object MRFProperties;
}
rotorZone
{
    active yes;
    cellZone rotor;
    nonRotatingPatches (stator);
    origin (0 0 0);
    axis (0 0 1);
    omega constant 100;
} rotor 为预先建立的 cellZone，omega 的单位为 rad/s。nonRotatingPatches 指定区域内保持静止的边界。MRF 在固定网格上采用旋转参考系近似处理。 SRFProperties 配置单参考系模型，常用 SRFModel rpm 和 rpmCoeffs/rpm，以 rpm 表示转速。使用两种模型时应分别采用对应的角速度单位。

下例采用位移拉普拉斯方法平滑网格运动，并通过 0/pointDisplacement 指定位移。求解器需支持该运动模型。 dynamicFvMesh dynamicMotionSolverFvMesh;
motionSolverLibs ("libfvMotionSolvers.so");
solver displacementLaplacian;
displacementLaplacianCoeffs
{
    diffusivity uniform;
} pointDisplacement 为 pointVectorField，采用长度量纲。运动壁面指定相应位移，固定壁面指定零位移。motionSolver 或兼容键 solver 按 v2512 对应模型的接口设置。 模型或功能 配置项 相关参数 规定刚体运动 solidBodyMotionFvMesh、solidBodyMotionFunction 及相应系数 旋转中心、轴、速度或时间函数 六自由度 sixDoFRigidBodyMotion 运动求解器 mass、momentOfInertia、centreOfMass、力矩参考与约束 自适应细化 dynamicRefineFvMesh field、refineInterval、lowerRefineLevel、upperRefineLevel、unrefineLevel 细化限制 maxRefinement、maxCells、nBufferLayers 内存估计和细化一致性 拓扑改变通量修正 correctFluxes 通量和关联速度字段的配对，依求解器设置 重叠网格 dynamicOversetFvMesh 等、oversetInterpolation zoneID、overset patch、孔切割和插值层 先运行 moveDynamicMesh 检查网格运动，重点检查运动过程中质量最差的时刻，再进行流场求解。运动和拓扑变化类型应处于求解器的支持范围内。 刚体运动（最简单） dynamicFvMesh   dynamicMotionSolverFvMesh;
motionSolver    solidBody;
solidBodyMotionFunction  rotatingMotion;
rotatingMotionCoeffs
{
    origin  (0 0 0);
    axis    (0 0 1);
    omega   6.28;                 // rad/s
}
cellZone        rotor;            // 只让这个 zone 动 其他运动函数：oscillatingLinearMotion、linearMotion、SDA、tabulated6DoFMotion、multiMotion。 六自由度耦合（自由运动物体） motionSolver    sixDoFRigidBodyMotion;
sixDoFRigidBodyMotionCoeffs
{
    patches         (floatingObject);
    innerDistance   0.05;
    outerDistance   0.35;
    mass            9.6;
    centreOfMass    (0.5 0.45 0.4);
    momentOfInertia (0.08 0.08 0.06);
    accelerationRelaxation 0.7;
    solver          { type Newmark; }
    constraints     { zAxis { sixDoFRigidBodyMotionConstraint line; direction (0 0 1);} }
} 动态加密（AMR） dynamicFvMesh   dynamicRefineFvMesh;
refineInterval  10;
field           alpha.water;      // 按哪个场判断
lowerRefineLevel 0.001;
upperRefineLevel 0.999;
maxRefinement   2;
maxCells        2000000;
nBufferLayers   1; 用途：VOF 里只在界面附近加密，单元数可以省一个量级。

// constant/regionProperties 片段
regions
(
    fluid (air)
    solid (solidBlock)
); air 和 solidBlock 分别配置 constant/区域名/polyMesh、热物性文件以及 system/区域名 下的 fvSchemes 和 fvSolution。初始场位于 0/区域名/。流固界面通常采用 mappedWall 网格边界，并设置相邻区域映射和温度耦合条件。 文件 用途 主要参数 constant/radiationProperties 辐射模型 radiation on/off、radiationModel（P1、fvDOM、viewFactor 等）、solverFreq 及模型专用系数 constant/viewFactorsDict 视角因子设置 指定参与边界，按生成工具配置积分或射线参数 constant/chemistryProperties 化学积分 chemistry、chemistryType 中的 solver/method、initialChemicalTimeStep、ODE 系数 constant/combustionProperties 燃烧闭合模型 combustionModel 及 PaSR、EDC、laminar 等模型的专用系数 constant/reactions 反应机理 物种名称、反应式、速率系数；可由 chemkinToFoam 转换 constant/thermophysicalProperties.相名 多相分相热物性 各相 thermoType、状态方程、热容与输运 constant/phaseProperties Euler 多相体系或特定多相模型 phases、直径模型、阻力、升力、传热等分相和相间模型 constant/kinematicCloudProperties 等 拉格朗日粒子云 solution、constantProperties、subModels、injectionModels、forces、patchInteractionModel constant/sprayCloudProperties 喷雾云 在粒子设置基础上加入 atomization、breakup、phaseChange 等模型 constant/porosityProperties 部分求解器的多孔阻力入口 zone、Darcy–Forchheimer 系数及局部坐标；也可通过 fvOptions 配置 constant/solidProperties 或 mechanicalProperties 固体材料 按固体求解器设置 rho、E、nu 和 planeStress；此处 nu 表示泊松比 system/faSchemes、faSolution 的有限面积位置 面上离散与求解 v2512 常位于 system/finite-area/；使用 faMesh 对应的字段和算子 system/finite-area/faMeshDefinition 有限面积网格生成 polyMeshPatches、boundary、面选取和边界命名 system/optimisationDict 伴随优化 优化类型、设计变量、目标函数、约束和更新算法 专用模型的配置项随物种机理、粒子模型、燃烧模型和优化算法变化。可通过 find "$FOAM_TUTORIALS" -name 文件名 查找对应求解器算例，并据模型源码确定条目层级及参数。

// constant/regionProperties 片段
regions
(
    fluid (air)
    solid (solidBlock)
); air 和 solidBlock 分别配置 constant/区域名/polyMesh、热物性文件以及 system/区域名 下的 fvSchemes 和 fvSolution。初始场位于 0/区域名/。流固界面通常采用 mappedWall 网格边界，并设置相邻区域映射和温度耦合条件。 文件 用途 主要参数 constant/radiationProperties 辐射模型 radiation on/off、radiationModel（P1、fvDOM、viewFactor 等）、solverFreq 及模型专用系数 constant/viewFactorsDict 视角因子设置 指定参与边界，按生成工具配置积分或射线参数 constant/chemistryProperties 化学积分 chemistry、chemistryType 中的 solver/method、initialChemicalTimeStep、ODE 系数 constant/combustionProperties 燃烧闭合模型 combustionModel 及 PaSR、EDC、laminar 等模型的专用系数 constant/reactions 反应机理 物种名称、反应式、速率系数；可由 chemkinToFoam 转换 constant/thermophysicalProperties.相名 多相分相热物性 各相 thermoType、状态方程、热容与输运 constant/phaseProperties Euler 多相体系或特定多相模型 phases、直径模型、阻力、升力、传热等分相和相间模型 constant/kinematicCloudProperties 等 拉格朗日粒子云 solution、constantProperties、subModels、injectionModels、forces、patchInteractionModel constant/sprayCloudProperties 喷雾云 在粒子设置基础上加入 atomization、breakup、phaseChange 等模型 constant/porosityProperties 部分求解器的多孔阻力入口 zone、Darcy–Forchheimer 系数及局部坐标；也可通过 fvOptions 配置 constant/solidProperties 或 mechanicalProperties 固体材料 按固体求解器设置 rho、E、nu 和 planeStress；此处 nu 表示泊松比 system/faSchemes、faSolution 的有限面积位置 面上离散与求解 v2512 常位于 system/finite-area/；使用 faMesh 对应的字段和算子 system/finite-area/faMeshDefinition 有限面积网格生成 polyMeshPatches、boundary、面选取和边界命名 system/optimisationDict 伴随优化 优化类型、设计变量、目标函数、约束和更新算法 专用模型的配置项随物种机理、粒子模型、燃烧模型和优化算法变化。可通过 find "$FOAM_TUTORIALS" -name 文件名 查找对应求解器算例，并据模型源码确定条目层级及参数。 radiation       on;
radiationModel  P1;              // none / P1 / fvDOM / viewFactor / opaqueSolid
solverFreq      10;
absorptionEmissionModel constantAbsorptionEmission;
constantAbsorptionEmissionCoeffs { absorptivity 0.5; emissivity 0.5; E 0; }
scatterModel    none;

// constant/g 完整示例
FoamFile
{
    version 2.0; format ascii;
    class uniformDimensionedVectorField; object g;
}
dimensions [0 1 -2 0 0 0 0];
value (0 -9.81 0); g 定义重力矢量，其方向与几何坐标系对应。hRef 定义静水压参考高度，通常采用 uniformDimensionedScalarField 和长度量纲；pRef 按求解器接口设置。fvSolution 中的 pRefCell/pRefValue 用于压力方程参考值，作用不同。

下例给出与第 7 章二维通道网格对应的速度和压力场。内部初始速度等于入口速度，壁面采用无滑移条件，出口速度采用零梯度条件。 FoamFile
{
    version 2.0; format ascii;
    class volVectorField; object U;
}
dimensions [0 1 -1 0 0 0 0];
internalField uniform (1 0 0);
boundaryField
{
    inlet { type fixedValue; value uniform (1 0 0); }
    outlet { type zeroGradient; }
    walls { type noSlip; }
    frontAndBack { type empty; }
} FoamFile
{
    version 2.0; format ascii;
    class volScalarField; object p;
}
dimensions [0 2 -2 0 0 0 0];
internalField uniform 0;
boundaryField
{
    inlet { type zeroGradient; }
    outlet { type fixedValue; value uniform 0; }
    walls { type zeroGradient; }
    frontAndBack { type empty; }
} 本例 p 为运动学压力，适用于相应的不可压缩求解器。采用绝对压力的可压缩求解器时，dimensions 设为 [1 -1 -2 0 0 0 0]，压力值按状态方程设置，如 101325 Pa。

下例给出与第 7 章二维通道网格对应的速度和压力场。内部初始速度等于入口速度，壁面采用无滑移条件，出口速度采用零梯度条件。 FoamFile
