    class volScalarField; object p;
}
dimensions [0 2 -2 0 0 0 0];
internalField uniform 0;
boundaryField
{
    inlet { type zeroGradient; }
    outlet { type fixedValue; value uniform 0; }
    walls { type zeroGradient; }
    frontAndBack { type empty; }
} 本例 p 为运动学压力，适用于相应的不可压缩求解器。采用绝对压力的可压缩求解器时，dimensions 设为 [1 -1 -2 0 0 0 0]，压力值按状态方程设置，如 101325 Pa。

温度场 T 采用温度量纲，初值示例为 internalField uniform 300;。等温壁面使用 fixedValue，绝热壁面通常使用 zeroGradient。externalWallHeatFluxTemperature 可指定热通量或功率，并通过 mode、kappaMethod 等参数定义施加方式和导热率来源。 p_rgh 表示扣除静水压项后的压力，常见定义为 p_rgh = p - rho*gh。参考高度和量纲由求解器确定，不可压缩 Boussinesq 模型可采用归一化形式。恢复实际压力时，应按该求解器的定义还原静水压项。 alpha.water 表示水相体积分数，为无量纲量，取值范围为 [0,1]；多相体系中各相体积分数之和为 1。入口可指定相分数，开放边界可采用 inletOutlet，壁面可采用 zeroGradient 或接触角条件。字段后缀 water 与 phases 中的相名对应。 type 作用 zeroGradient 壁面标准做法（不可压） fixedValue 出口给定压力（不可压时值是 p/ρ） totalPressure 给定总压，静压随速度自动调整 fixedFluxPressure 壁面与动网格的正确做法：保证边界通量与速度边界一致 prghPressure / prghTotalPressure 多相流的 p_rgh（已扣除静水压） freestreamPressure 远场 waveTransmissive 无反射出口（可压缩，防激波反射回来） // 不可压出口
outlet { type fixedValue; value uniform 0; }

// 壁面（含浮力/动网格时必须这样写）
walls  { type fixedFluxPressure; value uniform 0; }

// 可压超声速出口，防止反射
outlet
{
    type            waveTransmissive;
    field           p;
    gamma           1.4;
    value           uniform 1e5;
} 为什么壁面上不能简单写 zeroGradient：有重力或者动网格时，壁面法向压力梯度并不为零（要平衡重力/加速度）。fixedFluxPressure 会自动按动量方程推出正确的梯度。写错的后果是质量不守恒、界面处出现虚假速度。 p 和 p_rgh 的区别：多相流和浮力问题里求解的是 p_rgh = p − ρg·h（扣掉静水压），这样数值上更好解。你在 0/ 里给的是 p_rgh，p 由程序算出。边界条件要给在 p_rgh 上。

field       alpha.water;
type        sphere;            // sphere / plane / cylinder / sin
origin      (0.5 0.5 0);
radius      0.15;
direction   (1 0 0); 比 setFields 精细：界面所在单元会得到精确的部分体积分数（而不是 0 或 1），用于界面收敛性验证。

// 放入 functions 内
pressureProbes
{
    type probes;
    libs ("libsampling.so");
    writeControl timeStep;
    writeInterval 1;
    fields (p U);
    probeLocations
    (
        (0.25 0.05 0.005)
        (0.75 0.05 0.005)
    );
} 探针位置应位于有效流体单元内，压力结果输出至 postProcessing/pressureProbes/起始时刻/p。冲击和快速瞬态计算需按目标时间尺度设置采样频率，以记录峰值及波形变化。

转换面集合时需处理面方向信息。 用法：setsToZones [选项] 示例：setsToZones lineSample
{
    type sets;
    libs ("libsampling.so");
    writeControl writeTime;
    setFormat raw;
    interpolationScheme cellPoint;
    fields (U p);
    sets
    {
        centreline
        {
            type uniform;
            axis x;
            start (0.01 0.05 0.005);
            end (0.99 0.05 0.005);
            nPoints 100;
        }
    }
} axis 指定输出横坐标类型，nPoints 指定采样点数，interpolationScheme 指定单元或点插值方法。

sectionSample
{
    type surfaces;
    libs ("libsampling.so");
    writeControl writeTime;
    surfaceFormat vtk;
    fields (U p);
    interpolationScheme cellPoint;
    surfaces
    {
        midPlane
        {
            type cuttingPlane;
            planeType pointAndNormal;
            pointAndNormalDict
            {
                point (0.5 0 0);
                normal (1 0 0);
            }
            interpolate true;
        }
    }
} 面采样还支持 patch、isoSurface 等类型。采用 isoSurface 时，通过字段、等值和采样算法定义所需相界面或涡结构。

bodyForces
{
    type forces;
    libs ("libforces.so");
    patches (walls);
    p p;
    U U;
    rho rhoInf;
    rhoInf 1000;
    CofR (0 0 0);
    writeControl timeStep;
    writeInterval 1;
} 下例使用参考密度处理不可压缩压力场。可压缩计算通常指定实际 rho 字段及对应压力形式。CofR 定义力矩参考中心，压力基准应与载荷积分采用的压力定义一致。 计算力系数时，将 type 设为 forceCoeffs，并指定 liftDir、dragDir、pitchAxis、magUInf、lRef 和 Aref。若阻力沿 x 方向、升力沿 y 方向，可设置 dragDir (1 0 0); liftDir (0 1 0); pitchAxis (0 0 1);。lRef 和 Aref 分别为归一化参考长度和面积，二维算例的参考面积需计入所取厚度。

